{
  "findings": [
    {
      "check_id": "CKV_AZURE_93",
      "title": "Azure SQL Database missing threat detection policy",
      "resource": "azurerm_mssql_database.main",
      "severity": "HIGH",
      "explanation": "The Azure SQL Database is not configured with a threat detection policy, which is essential for identifying potential security threats."
    },
    {
      "check_id": "CKV_AZURE_102",
      "title": "Azure SQL Database missing audit policy",
      "resource": "azurerm_mssql_database.main",
      "severity": "HIGH",
      "explanation": "The Azure SQL Database is not configured with an audit policy, which is crucial for monitoring and logging database activities."
    }
  ],
  "patched_code": "resource "azurerm_mssql_database" "main" {
  name           = "${var.project_name}-database"
  server_id      = azurerm_mssql_server.main.id
  collation      = "SQL_Latin1_General_CP1_CI_AS"
  license_type   = "LicenseIncluded"
  max_size_gb    = 20
  sku_name       = "S0"
  tags = var.common_tags

  extended_auditing_policy {
    storage_endpoint                        = azurerm_storage_account.example.primary_blob_endpoint
    storage_account_access_key              = azurerm_storage_account.example.primary_access_key
    storage_account_access_key_is_secondary = false
    retention_in_days                       = 6
  }

  threat_detection_policy {
    state                      = "Enabled"
    storage_endpoint           = azurerm_storage_account.example.primary_blob_endpoint
    storage_account_access_key = azurerm_storage_account.example.primary_access_key
    disabled_alerts            = []
    retention_days             = 6
  }
}",
  "fix_summary": "Added extended auditing policy and threat detection policy to the Azure SQL Database to enhance security monitoring and threat detection."
}
